/**
 * `octane/data/client` opens a page's store over the application's data
 * worker. The Octane Vite and Rspack plugins generate it from the module their
 * `dataClient` option names; this placeholder only carries its types.
 */
import type { OpenDataStoreOptions } from './data-client.js';
import type { DataStore } from './store.js';

throw new Error(
	'octane/data/client is generated by the Octane Vite or Rspack plugin from its `dataClient` option',
);

/**
 * The store of `account`, the signed-in account's ID: a replica of the data
 * worker's owner, which every tab of the account shares, or a store of its own
 * where no worker can serve the page.
 */
export declare function openDataStore(account: string, options?: OpenDataStoreOptions): DataStore;
